def _http(handler) -> httpx2.AsyncClient:
    return httpx2.AsyncClient(transport=httpx2.MockTransport(handler))


def _gql(handler, query="query { x }", **kwargs):
    async def run():
        async with _http(handler) as http:
            return await client.gql(query, client=http, **kwargs)

    return asyncio.run(run())


# --- client -----------------------------------------------------------------------------


def test_gql_sends_the_token_and_returns_data():
    seen = {}

    def handler(request):
        seen["auth"] = request.headers["authorization"]
        seen["body"] = json.loads(request.content)
        return httpx2.Response(200, json={"data": {"x": 1}})

    assert _gql(handler, variables={"id": 5}) == {"x": 1}
    assert seen["auth"] == "Bearer test-token"
    assert seen["body"] == {"query": "query { x }", "variables": {"id": 5}}


def test_missing_token_is_a_clear_error(monkeypatch):
    monkeypatch.setattr(client, "get_settings", Settings)
    with pytest.raises(client.MissingTokenError, match="ds settings sync"):
        _gql(lambda _: httpx2.Response(200, json={"data": {}}))


@pytest.mark.parametrize(
    ("status", "body", "error", "match"),
    [
        (429, {"success": False, "message": "Rate limit exceeded - api-token"}, client.RateLimitError, "80 requests"),
        (
            400,
            {"success": False, "fields": None, "message": "Query complexity too high. A maximum (actual: 1235)"},
            client.ComplexityError,
            "1235 objects, the limit is 1000",
        ),
        (401, {"message": "Invalid authentication token"}, client.StartggError, "expire 365 days"),
        (200, {"errors": [{"message": 'Cannot query field "nope" on type "Set".'}]}, client.StartggError, "nope"),
        (500, {"message": "boom"}, client.StartggError, "HTTP 500"),
    ],
)
def test_error_bodies_become_typed_errors(status, body, error, match):
    with pytest.raises(error, match=match) as caught:
        _gql(lambda _: httpx2.Response(status, json=body))
    if error is client.ComplexityError:
        assert caught.value.actual == 1235


def test_each_request_is_logged_without_the_token(call_logs):
    def handler(_):
        return httpx2.Response(200, json={"data": {"x": 1}, "extensions": {"queryComplexity": 7}})

    _gql(handler, query="query PlayerSets($id: ID!) { x }", variables={"id": 5, "page": 2})
    (record,) = call_logs
    assert record["kind"] == "graphql"
    assert record["source"] == "startgg"
    assert record["op"] == "PlayerSets"
    assert record["variables"] == {"id": 5, "page": 2}
    assert (record["status"], record["objects"]) == (200, 7)
    assert record["bytes"] > 0
    assert isinstance(record["ms"], int)
    assert "error" not in record
    assert "test-token" not in repr(record)


def test_a_failed_request_is_logged_with_its_error(call_logs):
    with pytest.raises(client.StartggError):
        _gql(lambda _: httpx2.Response(500, json={"message": "boom"}))
    (record,) = call_logs
    assert record["status"] == 500
    assert "boom" in record["error"]


