def _entrant(entrant_id: int, player_id: int, tag: str, partner: int | None = None) -> dict:
    players = [{"player": {"id": player_id, "gamerTag": tag, "prefix": "FaZe" if tag == "Sparg0" else None}}]
    if partner:
        players.append({"player": {"id": partner, "gamerTag": "partner", "prefix": None}})
    return {"id": entrant_id, "name": tag, "initialSeedNum": 2, "isDisqualified": False, "participants": players}


def _set_node(n: int, *, videogame: int = 1386, doubles: bool = False, completed: bool = True, vod: bool = False):
    """Canned set number `n` (1 = newest): Sparg0 (entrant n*10+1) beats acola (n*10+2) 2-1"""
    mine, theirs = n * 10 + 1, n * 10 + 2
    games = [
        {
            "orderNum": order,
            "winnerId": winner,
            "entrant1Score": 2,
            "entrant2Score": 0,
            "stage": {"id": 378, "name": "Pokémon Stadium 2"} if order == 1 else None,
            "selections": [
                {"entrant": {"id": mine}, "selectionType": "CHARACTER", "selectionValue": 1297},
                {"entrant": {"id": theirs}, "selectionType": "CHARACTER", "selectionValue": 1777},
            ],
        }
        for order, winner in ((2, theirs), (1, mine), (3, mine))  # out of order on purpose
    ]
    return {
        "id": 1000 + n,
        "completedAt": _T0 - n * 86_400 if completed else None,
        "fullRoundText": "Winners Final",
        "round": 5,
        "totalGames": 3,
        "winnerId": mine,
        "displayScore": "Sparg0 2 - acola 1",
        "vodUrl": "https://youtu.be/abc" if vod else None,
        "state": 3 if completed else 2,
        "event": {
            "id": 500 + n,
            "name": "Ultimate Singles",
            "slug": f"tournament/weekly-{n}/event/ultimate-singles",
            "startAt": _T0 - n * 86_400,
            "isOnline": False,
            "numEntrants": 64,
            "videogame": {"id": videogame},
            "tournament": {"id": 900 + n, "name": f"Weekly {n}", "slug": f"tournament/weekly-{n}", "startAt": _T0},
        },
        "slots": [
            {
                "entrant": _entrant(mine, SPARG0, "Sparg0", partner=7 if doubles else None),
                "standing": {"placement": 1, "stats": {"score": {"value": 2}}},
            },
            {
                "entrant": _entrant(theirs, ACOLA, "acola"),
                "standing": {"placement": 2, "stats": {"score": {"value": 1}}},
            },
        ],
        "games": games,
    }


@pytest.fixture
def fake_api(monkeypatch):
    """Replace client.gql: `fake.sets` paged as start.gg would, `fake.calls` the requests"""

    class Fake:
        sets: list = []  # noqa: RUF012  # reset per test by the fixture
        calls: list = []  # noqa: RUF012
        too_many_above: int | None = None
        answers: dict = {}  # noqa: RUF012

    fake = Fake()
    fake.sets, fake.calls, fake.answers = [], [], {}

    async def gql(query, variables=None, **_):
        variables = variables or {}
        name = re.search(r"query (\w+)", query).group(1)
        fake.calls.append((name, variables))
        if name == "Videogame":
            return _VIDEOGAME
        if name == "PlayerSets":
            per_page, page = variables["perPage"], variables["page"]
            if fake.too_many_above and per_page > fake.too_many_above:
                raise client.ComplexityError("too many", per_page * 100)
            nodes = fake.sets[(page - 1) * per_page : page * per_page]
            info = {"total": len(fake.sets), "totalPages": -(-len(fake.sets) // per_page), "page": page}
            return {
                "player": {"id": variables["id"], "sets": {"pageInfo": info | {"perPage": per_page}, "nodes": nodes}}
            }
        return fake.answers[name]

    monkeypatch.setattr(client, "gql", gql)
    return fake


def _set_pages(fake) -> list[int]:
    return [v["page"] for name, v in fake.calls if name == "PlayerSets"]


