def test_set_is_parsed_with_results_and_char_groups(fake_api):
    fake_api.sets = [_set_node(1, vod=True)]
    (s,) = asyncio.run(startgg.player_sets(SPARG0))
    assert s.id == "1001"
    assert s.completed_at == dt.datetime.fromtimestamp(_T0 - 86_400, dt.UTC)
    assert (s.round_text, s.display_score, s.vod_url) == ("Winners Final", "Sparg0 2 - acola 1", "https://youtu.be/abc")
    assert s.event.videogame_id == startgg.ULTIMATE
    assert s.event.tournament.name == "Weekly 1"

    mine, theirs = s.side_of(SPARG0), s.opponent_of(SPARG0)
    assert (mine.players[0].tag, mine.players[0].prefix, mine.seed) == ("Sparg0", "FaZe", 2)
    assert theirs.players[0].id == ACOLA
    # results are part of the data layer (the agent layer is what leaves them out)
    assert s.winner_entrant_id == mine.entrant_id
    assert (mine.score, mine.placement, theirs.score, theirs.placement) == (2, 1, 1, 2)

    assert [g.number for g in s.games] == [1, 2, 3]
    first = s.games[0]
    assert first.stage.name == "Pokémon Stadium 2"
    assert s.games[1].stage is None
    assert first.winner_entrant_id == mine.entrant_id
    char = first.character_of(mine.entrant_id)
    assert (char.name, char.char_group, char.char_icon) == ("Little Mac", "little_mac", "char_icons/little_mac.png")
    assert first.character_of(theirs.entrant_id).char_group == "steve"
    assert first.character_of(None) is None


