def test_queries_are_complete_documents():
    """Every fragment a query spreads is appended to it, and braces balance"""
    for name in queries.__all__:
        document = getattr(queries, name)
        assert document.count("{") == document.count("}"), name
        spread = set(re.findall(r"\.\.\.(\w+)", document))
        defined = set(re.findall(r"fragment (\w+) on", document))
        assert spread == defined, name


